//! 📠️ CCITT terminating and makeup codewords.
use semio_framework_value::{NativeDecodeControl,NativeEncodeControl,ValueError,ValueRefusalKind};
fn invalid(message:&str)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
struct Bits<'a>{source:&'a[u8],at:usize,fill:u32}
impl Bits<'_>{fn bit(&mut self)->Result<u32,ValueError>{let byte=*self.source.get(self.at/8).ok_or_else(||invalid("TIFF CCITT truncated codeword"))?;let bit=u32::from((byte>>if self.fill==2{self.at%8}else{7-self.at%8})&1);self.at+=1;Ok(bit)}fn align(&mut self){self.at=self.at.div_ceil(8)*8;}fn eol(&mut self)->Result<(),ValueError>{let mut zeros=0;while self.bit()?==0{zeros+=1;if zeros>64{return Err(invalid("TIFF CCITT EOL fill extent"))}}if zeros<11{return Err(invalid("TIFF CCITT EOL"))}Ok(())}fn run(&mut self,color:bool)->Result<usize,ValueError>{let table=if color{BLACK}else{WHITE};let mut total=0usize;loop{let mut code=0u32;let mut found=None;for length in 1..=13{code=code*2+self.bit()?;let key=(length<<13)|code;if let Ok(index)=table.binary_search_by_key(&key,|entry|entry.0){found=Some(table[index].1 as usize);break;}}let value=found.ok_or_else(||invalid("TIFF CCITT run code"))?;total=total.checked_add(value).ok_or_else(||invalid("TIFF CCITT run overflow"))?;if value<64{return Ok(total)}}}}
fn paint(row:&mut[u8],from:usize,to:usize,color:bool)->Result<(),ValueError>{if to<from||to>row.len(){return Err(invalid("TIFF CCITT row extent"))}row[from..to].fill(u8::from(color));Ok(())}
fn one(bits:&mut Bits<'_>,row:&mut[u8])->Result<(),ValueError>{let(mut at,mut color,mut runs)=(0usize,false,0usize);while at<row.len(){let end=at.checked_add(bits.run(color)?).ok_or_else(||invalid("TIFF CCITT row overflow"))?;paint(row,at,end,color)?;at=end;color=!color;runs+=1;if runs>row.len()*2+2{return Err(invalid("TIFF CCITT empty runs"))}}Ok(())}
fn reference_pair(reference:&[u8],at:usize,color:bool,first:bool)->(usize,usize){let mut b1=reference.len();for position in (if first{at}else{at+1})..reference.len(){let before=if position==0{0}else{reference[position-1]};if reference[position]!=before&&reference[position]!=u8::from(color){b1=position;break;}}let b2=(b1+1..reference.len()).find(|position|reference[*position]!=reference[*position-1]).unwrap_or(reference.len());(b1,b2)}
fn two(bits:&mut Bits<'_>,row:&mut[u8],reference:&[u8])->Result<(),ValueError>{let(mut at,mut color,mut first,mut modes)=(0usize,false,true,0usize);while at<row.len(){let(mut code,mut mode)=(0u32,None);for length in 1..=7{code=code*2+bits.bit()?;mode=match(length,code){(1,1)=>Some(0),(3,3)=>Some(1),(3,2)=>Some(-1),(6,3)=>Some(2),(6,2)=>Some(-2),(7,3)=>Some(3),(7,2)=>Some(-3),(4,1)=>Some(10),(3,1)=>Some(11),_=>None};if mode.is_some(){break;}}let mode=mode.ok_or_else(||invalid("TIFF CCITT two-dimensional mode"))?;let(b1,b2)=reference_pair(reference,at,color,first);if mode==10{paint(row,at,b2,color)?;at=b2;}else if mode==11{let a1=at.checked_add(bits.run(color)?).ok_or_else(||invalid("TIFF CCITT run overflow"))?;let a2=a1.checked_add(bits.run(!color)?).ok_or_else(||invalid("TIFF CCITT run overflow"))?;paint(row,at,a1,color)?;paint(row,a1,a2,!color)?;at=a2;}else{let end=usize::try_from(b1 as i64+i64::from(mode)).map_err(|_|invalid("TIFF CCITT vertical extent"))?;paint(row,at,end,color)?;at=end;color=!color;}first=false;modes+=1;if modes>row.len()*2+2{return Err(invalid("TIFF CCITT mode work extent"))}}Ok(())}
/// 📥️ Decodes modified Huffman, Group3 and Group4 directly to native one-bit scanlines.
pub(super) fn decode(source:&[u8],compression:u32,width:usize,height:usize,fill:u32,options:u32,c:&mut NativeDecodeControl<'_>)->Result<Vec<u8>,ValueError>{let stride=width.div_ceil(8);let length=stride.checked_mul(height).ok_or_else(||invalid("TIFF CCITT raster extent"))?;let mut output=c.allocate_vec::<u8>(length)?;output.resize(length,0);let mut reference=c.allocate_vec::<u8>(width)?;reference.resize(width,0);let mut row=c.allocate_vec::<u8>(width)?;row.resize(width,0);let mut bits=Bits{source,at:0,fill};c.begin_stage(width.checked_mul(height).ok_or_else(||invalid("TIFF CCITT work extent"))?)?;for y in 0..height{row.fill(0);let dimensional=if compression==4{true}else if compression==3{bits.eol()?;options&1!=0&&bits.bit()?==0}else{false};if dimensional{two(&mut bits,&mut row,&reference)?}else{one(&mut bits,&mut row)?}for(x,value)in row.iter().enumerate(){output[y*stride+x/8]|=*value<<(7-x%8);c.step()?;}reference.copy_from_slice(&row);if compression==2{bits.align();}}Ok(output)}
struct Writer{bytes:Vec<u8>,at:usize}
impl Writer{fn bit(&mut self,value:u32){if self.at/8==self.bytes.len(){self.bytes.push(0)}self.bytes[self.at/8]|=(value as u8)<<(7-self.at%8);self.at+=1;}fn code(&mut self,code:u32,length:u32){for bit in (0..length).rev(){self.bit((code>>bit)&1)}}fn run(&mut self,mut run:usize,color:bool){let table=if color{BLACK}else{WHITE};while run>=64{let count=run.min(2560)/64*64;let(key,_)=table.iter().find(|entry|entry.1 as usize==count).unwrap();self.code(key&8191,key>>13);run-=count;}let(key,_)=table.iter().find(|entry|entry.1 as usize==run).unwrap();self.code(key&8191,key>>13);}}
/// 📤️ Emits lossless bilevel samples using bounded horizontal CCITT coding.
pub(super) fn encode(raw:&[u8],compression:u32,width:usize,height:usize,c:&mut NativeEncodeControl<'_>)->Result<Vec<u8>,ValueError>{let capacity=width.checked_mul(height).and_then(|n|n.checked_mul(4)).and_then(|n|n.checked_add(height*4+4)).ok_or_else(||invalid("TIFF CCITT output extent"))?;let mut writer=Writer{bytes:c.allocate_vec::<u8>(capacity)?,at:0};let stride=width.div_ceil(8);c.begin_stage(width.checked_mul(height).ok_or_else(||invalid("TIFF CCITT work extent"))?)?;for y in 0..height{if compression==3{writer.code(1,12)}let(mut at,mut color)=(0usize,false);while at<width{if compression==4{writer.code(1,3)}let mut runs=0;let count=if compression==4{2}else{1};while runs<count{let begin=at;while at<width&&(((raw[y*stride+at/8]>>(7-at%8))&1)!=0)==color{at+=1;}writer.run(at-begin,color);color=!color;runs+=1;}c.checkpoint()?;}if compression==2{while writer.at%8!=0{writer.bit(0)}}c.advance(width)?;}if compression==4{writer.code(1,12);writer.code(1,12);}if compression==3{for _ in 0..6{writer.code(1,12);}}Ok(writer.bytes)}
